def fetch(page):
    if page == 3:
        raise RuntimeError("HTTP 503")
    return [{"order_id": page * 10 + i, "amount_cents": 100 * i - 50} for i in range(3)]

def run(pages):
    valid, dead, failed = [], [], []
    for page in pages:
        try:
            records = fetch(page)
        except RuntimeError:
            failed.append(page)
            continue
        for record in records:
            if record["amount_cents"] >= 0:
                valid.append(record)
            else:
                dead.append((record["order_id"], "negative amount"))
    return valid, dead, failed

valid, dead, failed = run([1, 2, 3, 4, 5])
print(len(valid))
print(dead)
print(failed)
share = len(failed) / 5
print("FAILED" if share > 0.25 else "OK with warnings" if failed else "OK")
